onChange.script:
if currentValue.value:
	self.custom.assetTree = {}

	import time
	time.sleep(0.5)
	self.custom.clearView = False

return

transforms.code:
#	system.perspective.print("Building mainView child asset instances")

	params = self.view.params.value
	expand = params['expand'] if value.has_key('expand') else True
	level = params['level'] if value.has_key('level') else 0

	info = []
	for item in value:
		children = []
		assets = []		
		for childAssets in value[item]:
			if childAssets != 'assetInfo': children.append(value[item][childAssets])
		info.append({'value': {'assetName': item, 'assetInfo': value[item]['assetInfo'], 'childAssets': children, 'assets': assets, 'expand': expand, 'level': level}})

#	system.perspective.print("Completed mainView child asset instances")

	return sorted(info, key=lambda x: x['value']['assetInfo']['sortOrder'])
